    func testRemoveAudioAndAudioBitrateOptionsApply() async throws {
        try skipUnlessInstalled()
        let folder = try newFolder()
        let source = try await makeClip(folder, "options.mp4")

        let muted = try await probe(try await convert(source, "mp4", options { $0.removeAudio = true }))
        XCTAssertNotNil(muted.video)
        XCTAssertNil(muted.audio)

        let tone = try await makeTone(folder, "bitrate.wav")
        let mp3 = try await probe(try await convert(tone, "mp3", options { $0.audioBitrateKbps = 128 }))
        XCTAssertEqual(mp3.audio?.bitRate, 128_000)
        let m4a = try await probe(try await convert(tone, "m4a", options { $0.audioBitrateKbps = 96 }))
        XCTAssertTrue((70_000...110_000).contains(try XCTUnwrap(m4a.audio).bitRate), "\(m4a.audio?.bitRate ?? 0)")

        // #37: mono speech Opus at 32 kbit/s, and a WAV for a phone system (mono, 8 kHz, 8-bit).
        let opus = try await probe(try await convert(tone, "opus", options { $0.audioBitrateKbps = 32; $0.audioChannels = 1 }))
        XCTAssertEqual(opus.audio?.codec, "opus")
        XCTAssertEqual(opus.audio?.channels, 1)
        let wav = try await probe(try await convert(tone, "wav", options { $0.audioChannels = 1; $0.audioSampleRate = 8000; $0.wavFormat = .pcm8 }))
        XCTAssertEqual(wav.audio?.codec, "pcm_u8")
        XCTAssertEqual(wav.audio?.channels, 1)
        XCTAssertEqual(wav.audio?.sampleRate, 8000)
        let float32 = try await probe(try await convert(tone, "wav", options { $0.wavFormat = .float32 }))
        XCTAssertEqual(float32.audio?.codec, "pcm_f32le")
        XCTAssertEqual(float32.audio?.channels, 2)
        XCTAssertEqual(float32.audio?.sampleRate, 44100)
    }

