    func testCoverArtAndTagsAreKept() async throws {
        try skipUnlessInstalled()
        let tools = try XCTUnwrap(Self.tools)
        let folder = try newFolder()
        let cover = FilePath.combine(folder, "cover.png")
        try await run(tools.ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i", "testsrc2=size=200x200", "-frames:v", "1", cover])
        let song = FilePath.combine(folder, "song.mp3")
        try await run(tools.ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i", "sine=duration=2", "-i", cover,
                                     "-map", "0:a", "-map", "1:v", "-c:v", "copy", "-disposition:v:0", "attached_pic", "-metadata", "title=노래 제목", song])

        // FLAC and M4A take a picture stream; Opus and Ogg a METADATA_BLOCK_PICTURE comment; MKA an attachment.
        var skipped: [String] = []
        for target in ["flac", "m4a", "opus", "ogg", "mka"] {
            if !Self.missingEncoders(target).isEmpty {
                skipped.append(target)
                continue
            }
            let output = try await convert(song, target)
            let probed = try await probe(output)
            XCTAssertTrue(probed.streams.contains { $0.cover && $0.codec == "png" }, "\(target): no cover")
            let tags = try await ProcessRunner.run(tools.ffprobe, ["-v", "error", "-show_entries", "format_tags=title,major_brand:stream_tags=title",
                                                                    "-of", "json", output], timeout: 60)
            XCTAssertTrue(tags.standardOutput.contains("노래 제목"), "\(target): title lost")
        }
        if !skipped.isEmpty { print("Not written by this FFmpeg (missing encoder): \(skipped)") }
    }

    // ───────────────────────── Progress and cancellation ─────────────────────────

    private final class FolderAllocator: OutputAllocator, @unchecked Sendable {
        private let folder: String
        private(set) var allocated: [String] = []
        init(_ folder: String) { self.folder = folder }

        func allocate(_ extension: String, suffix: String?) throws -> String? {
            let path = FilePath.combine(folder, "out\(suffix ?? "").\(`extension`)")
            allocated.append(path)
            return path
        }
    }

    /// Records every reported value synchronously.
    private final class Recorder: @unchecked Sendable {
        private let lock = NSLock()
        private var stored: [Double] = []
        private let onReport: (@Sendable (Double) -> Void)?
        init(_ onReport: (@Sendable (Double) -> Void)? = nil) { self.onReport = onReport }
        var values: [Double] { lock.withLock { stored } }
        var handler: ProgressHandler {
            { [self] value in
                lock.withLock { stored.append(value) }
                onReport?(value)
            }
        }
    }

    private func step(_ input: String, _ from: String, _ to: String, _ folder: String, _ media: MediaOptions = MediaOptions()) -> ConversionStep {
        var preset = Preset()
        preset.targetFormat = to
        preset.media = media
        return ConversionStep(inputPath: input, from: from, to: to, preset: preset, output: FolderAllocator(folder), workDirectory: folder)
    }

    func testProgressRisesWhileFfmpegWorks() async throws {
        try skipUnlessInstalled()
        let folder = try newFolder()
        // Long enough for several of FFmpeg's half-second progress reports.
        let source = try await makeClip(folder, "long.mp4", seconds: 40, size: "640x360", extra: ["-c:v", "libx264", "-preset", "ultrafast"])
        XCTAssertTrue(converter.status().isAvailable)

        let recorder = Recorder()
        let outputs = try await converter.convert(step(source, "mp4", "mkv", folder, options { $0.quality = .high }), progress: recorder.handler)

        XCTAssertTrue(FileManager.default.fileExists(try XCTUnwrap(outputs.first)))
        let values = recorder.values
        XCTAssertEqual(values.last, 1)
        XCTAssertTrue(zip(values, values.dropFirst()).allSatisfy { $0 <= $1 }, "\(values)")
        XCTAssertGreaterThanOrEqual(values.filter { $0 > 0.02 && $0 < 1 }.count, 3, "\(values)")
    }

